import {test} from 'node:test';import assert from 'node:assert/strict';import {createServer} from 'node:http';import {readFile,mkdir} from 'node:fs/promises';import path from 'node:path';import {chromium} from 'playwright';
const root=path.resolve(import.meta.dirname),results=path.resolve(process.env.OUTPUT_DIR||'../browser-results');await mkdir(results,{recursive:true});
const server=createServer(async(req,res)=>{try{const base=req.url.startsWith('/craft')?root:path.join(root,'dist');const decoded=decodeURIComponent(req.url.split('?')[0]);const rel=req.url.startsWith('/craft')?'browser.html':decoded.startsWith('/_expo/')?decoded.slice(1):'index.html';const file=path.resolve(base,rel);if(!file.startsWith(base+path.sep))throw Error('path');res.setHeader('Content-Type',file.endsWith('.js')?'text/javascript':file.endsWith('.html')?'text/html':'application/octet-stream');res.end(await readFile(file));}catch{res.statusCode=404;res.end('missing');}});
await new Promise(resolve=>server.listen(0,'127.0.0.1',resolve));const url=`http://127.0.0.1:${server.address().port}`;
const browser=await chromium.launch({executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',headless:true});
try{
await test('actual Expo screen account race, retry, item detail and invalid route',async()=>{
 const page=await browser.newPage({viewport:{width:390,height:844}});const errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.goto(url);await page.getByRole('button',{name:'Switch account',exact:true}).click();await page.getByRole('heading',{name:'Account B'}).waitFor();await page.getByLabel('Open B-0',{exact:true}).waitFor();await page.waitForTimeout(850);assert.equal(await page.getByLabel('Open A-0',{exact:true}).count(),0);
 await page.getByRole('switch',{name:'Offline fixture'}).click();await page.getByRole('button',{name:'Retry',exact:true}).click();await page.getByTestId('status').filter({hasText:'Offline fixture'}).waitFor();await page.getByRole('switch',{name:'Offline fixture'}).click();await page.getByRole('button',{name:'Retry',exact:true}).click();await page.getByLabel('Open B-0',{exact:true}).waitFor();await page.getByLabel('Open B-0',{exact:true}).click();await page.getByRole('heading',{name:'Detail B-0'}).waitFor();await page.screenshot({path:path.join(results,'expo-detail.png')});await page.goto(url+'/detail?id=wrong&account=A');await page.getByRole('heading',{name:/Invalid item/}).waitFor();assert.deepEqual(errors,[]);await page.close();
});
await test('adverse text, reversal, focus, reduced motion, cancellation and busy interaction',async()=>{
 const page=await browser.newPage({viewport:{width:390,height:844}});await page.goto(url+'/craft');await page.evaluate(()=>{fixture.setOpen(true);fixture.setOpen(false);fixture.setOpen(true);});await page.waitForTimeout(220);assert.equal(await page.locator('#panel').isVisible(),true);await page.getByRole('textbox',{name:'Panel input'}).focus();await page.evaluate(()=>fixture.setOpen(false));assert.equal(await page.locator('#toggle').evaluate(e=>e===document.activeElement),true);await page.emulateMedia({reducedMotion:'reduce'});await page.evaluate(()=>fixture.setOpen(true));assert.equal(await page.locator('#panel').isVisible(),true);await page.getByRole('button',{name:'Show full value'}).click();assert.equal(await page.locator('#full').textContent(),await page.locator('#value').textContent());assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true);
 await page.locator('#gesture').scrollIntoViewIfNeeded();const box=await page.locator('#gesture').boundingBox();await page.mouse.move(box.x+20,box.y+20);await page.mouse.down();const pointerId=await page.evaluate(()=>fixture.pointer);await page.locator('#gesture').dispatchEvent('pointerdown',{pointerId:99,isPrimary:false,clientX:90});assert.equal(await page.evaluate(()=>fixture.pointer),pointerId);await page.locator('#gesture').dispatchEvent('pointercancel',{pointerId});await page.mouse.up();assert.equal(await page.locator('#commits').textContent(),'0');await page.locator('#gesture').focus();await page.keyboard.press('Enter');assert.equal(await page.locator('#commits').textContent(),'1');
 await page.emulateMedia({reducedMotion:'no-preference'});await page.context().tracing.start({screenshots:true,snapshots:true});const start=Date.now();await page.evaluate(()=>{fixture.setOpen(false);fixture.busy();});await page.waitForTimeout(260);assert.equal(await page.locator('#panel').isVisible(),false);await page.context().tracing.stop({path:path.join(results,'busy-interaction.zip')});await page.screenshot({path:path.join(results,'craft.png')});console.log(JSON.stringify({completedBusyInteractionMs:Date.now()-start,scope:'single browser; no before/after performance claim'}));await page.evaluate(()=>{fixture.teardown();fixture.setOpen(true);});assert.equal(await page.locator('#panel').isVisible(),false);await page.close();
});
}finally{await browser.close();await new Promise(resolve=>server.close(resolve));}
